-- AUXY A13.25 catalog reset + 500 movies + 500 series/dramas
-- WARNING: this migration deletes the existing rows in movies/series and dependent seasons/episodes via CASCADE.
-- Run only after backup if you need the old catalog.

begin;

do $$ begin
  if to_regclass('public.movies') is null then raise exception 'public.movies is missing'; end if;
  if to_regclass('public.series') is null then raise exception 'public.series is missing'; end if;
end $$;

alter table public.movies add column if not exists banner_url text;
alter table public.movies add column if not exists metadata_provider text default 'cinemeta';
alter table public.movies add column if not exists metadata_search_title text;
alter table public.movies add column if not exists is_new_release boolean not null default false;
alter table public.movies add column if not exists is_iranian boolean not null default false;
alter table public.movies add column if not exists catalog_rank integer;

alter table public.series add column if not exists banner_url text;
alter table public.series add column if not exists metadata_provider text default 'cinemeta';
alter table public.series add column if not exists metadata_search_title text;
alter table public.series add column if not exists is_new_release boolean not null default false;
alter table public.series add column if not exists is_iranian boolean not null default false;
alter table public.series add column if not exists content_kind text default 'series';
alter table public.series add column if not exists catalog_rank integer;

create table if not exists public.auxy_catalog_settings(
  id integer primary key default 1 check (id=1),
  artwork_provider text not null default 'cinemeta' check (artwork_provider in ('cinemeta','tvmaze','custom')),
  custom_poster_template text,
  custom_banner_template text,
  updated_at timestamptz not null default now()
);
alter table public.auxy_catalog_settings enable row level security;
drop policy if exists auxy_catalog_settings_public_read on public.auxy_catalog_settings;
create policy auxy_catalog_settings_public_read on public.auxy_catalog_settings for select to anon, authenticated using (true);
drop policy if exists auxy_catalog_settings_admin_write on public.auxy_catalog_settings;
create policy auxy_catalog_settings_admin_write on public.auxy_catalog_settings for insert to authenticated with check (
  exists (select 1 from public.profiles p where p.id=auth.uid() and (lower(p.username) in ('auxy','ali','support','rezabzm') or p.role in ('owner','publisher','admin')))
);
drop policy if exists auxy_catalog_settings_admin_update on public.auxy_catalog_settings;
create policy auxy_catalog_settings_admin_update on public.auxy_catalog_settings for update to authenticated using (
  exists (select 1 from public.profiles p where p.id=auth.uid() and (lower(p.username) in ('auxy','ali','support','rezabzm') or p.role in ('owner','publisher','admin')))
) with check (
  exists (select 1 from public.profiles p where p.id=auth.uid() and (lower(p.username) in ('auxy','ali','support','rezabzm') or p.role in ('owner','publisher','admin')))
);
insert into public.auxy_catalog_settings(id) values(1) on conflict(id) do nothing;

-- Empty previous media catalog.
truncate table public.series_episodes, public.series_seasons, public.movies, public.series restart identity cascade;

