d","metadata_provider":"cinemeta","metadata_search_title":"Taaza Khabar","is_new_release":false,"is_iranian":false,"catalog_rank":500}]$auxy_catalog$::jsonb as data), rows as (
 select * from jsonb_to_recordset((select data from payload)) as x(
  title text, description text, year integer, content_kind text, poster_url text, banner_url text, published boolean, genres text[], age_rating text, language text, country text, release_status text, metadata_provider text, metadata_search_title text, is_new_release boolean, is_iranian boolean, catalog_rank integer
 ))
insert into public.series(title,description,year,content_kind,poster_url,banner_url,published,genres,age_rating,language,country,release_status,metadata_provider,metadata_search_title,is_new_release,is_iranian,catalog_rank)
select title,description,year,coalesce(content_kind,'series'),poster_url,banner_url,published,genres,age_rating,language,country,release_status,metadata_provider,metadata_search_title,is_new_release,is_iranian,catalog_rank from rows;

-- Every seeded series starts with an empty Season 1 so Studio can add the first video immediately.
insert into public.series_seasons(series_id,season_number,title)
select id,1,'فصل 1' from public.series where published=true;

create index if not exists idx_movies_catalog_rank on public.movies(catalog_rank);
create index if not exists idx_movies_new_release on public.movies(is_new_release) where published=true;
create index if not exists idx_movies_iranian on public.movies(is_iranian) where published=true;
create index if not exists idx_series_catalog_rank on public.series(catalog_rank);
create index if not exists idx_series_new_release on public.series(is_new_release) where published=true;
create index if not exists idx_series_iranian on public.series(is_iranian) where published=true;

drop function if exists public.auxy_ai_search_catalog(text, integer);
create or replace function public.auxy_ai_search_catalog(p_query text,p_limit integer default 20)
returns setof jsonb language sql stable security invoker set search_path=public as $$
  with p as (select trim(coalesce(p_query,'')) q, greatest(1,least(coalesce(p_limit,20),80)) lim), all_rows as (
    select 'movie'::text media_type, m.catalog_rank rank, m.is_new_release, m.is_iranian, m.imdb_rating, m.created_at, to_jsonb(m) j,
      lower(concat_ws(' ',m.title,m.description,m.director,m.country,m.language,array_to_string(m.cast_names,' '),array_to_string(m.genres,' '),m.metadata_search_title)) search_text from public.movies m where m.published=true
    union all
    select 'series'::text media_type, s.catalog_rank rank, s.is_new_release, s.is_iranian, null::numeric imdb_rating, s.created_at, to_jsonb(s) j,
      lower(concat_ws(' ',s.title,s.description,s.country,s.language,array_to_string(s.genres,' '),s.metadata_search_title)) search_text from public.series s where s.published=true
  ), scored as (
    select a.*,case when p.q='' then 0 else
      (case when lower(coalesce(a.j->>'title',''))=lower(p.q) then 100 else 0 end) +
      (case when lower(a.search_text) like '%'||lower(p.q)||'%' then 40 else 0 end) +
      coalesce((select sum(case when length(trim(t))>=2 and a.search_text like '%'||lower(trim(t))||'%' then 8 else 0 end) from regexp_split_to_table(lower(p.q),'[^[:alnum:]_آ-ی]+') t),0) +
      (case when a.is_iranian and lower(p.q) like '%iran%' then 18 else 0 end) +
      (case when lower(p.q) like '%ایران%' and a.is_iranian then 18 else 0 end) +
      (case when lower(p.q) like '%سریال%' and a.media_type='series' then 16 else 0 end) +
      (case when lower(p.q) like '%دراما%' and a.media_type='series' then 16 else 0 end) +
      (case when lower(p.q) like '%جدید%' and a.is_new_release then 14 else 0 end) +
      (case when lower(p.q) like '%new%' and a.is_new_release then 14 else 0 end) +
      (case when a.imdb_rating is not null then least(5,a.imdb_rating*.5) else 0 end) end score
    from all_rows a cross join p)
  select jsonb_build_object('media_type',s.media_type) || s.j from scored s cross join p where p.q='' or s.score>0 order by s.score desc,s.is_new_release desc,s.is_iranian desc,coalesce(s.imdb_rating,0) desc,s.rank nulls last,s.created_at desc limit (select lim from p);
$$;
revoke all on function public.auxy_ai_search_catalog(text,integer) from public;
grant execute on function public.auxy_ai_search_catalog(text,integer) to anon,authenticated;

commit;

